// Package cni renders the manifests of the optional third-party network
// plugins (open-source Calico and Cilium) installed instead of OVN-Kubernetes.
//
// The agent installer accepts networkType Calico or Cilium (assisted-service,
// OCP 4.22+) and applies the plugin's manifests from the install dir's
// openshift/ folder. Those manifests are embedded here, generated by
// hack/update-cni-manifests.sh; the offered versions are exactly the version
// directories found under manifests/<plugin>/.
package cni

import (
	"bytes"
	"embed"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strconv"
	"strings"
	"text/template"
)

const (
	OVNKubernetes = "OVNKubernetes"
	Calico        = "Calico"
	Cilium        = "Cilium"
)

// MinOCPMinor is the first OpenShift 4.x minor whose agent installer accepts
// networkType Calico/Cilium (assisted-service network_type enum).
const MinOCPMinor = 22

//go:embed manifests
var manifestsFS embed.FS

// Plugin describes one choice offered by the wizard.
type Plugin struct {
	NetworkType string `json:"networkType"`
	DisplayName string `json:"displayName"`
	// Versions newest first; empty for OVNKubernetes (part of the payload).
	Versions      []string `json:"versions,omitempty"`
	MinOCPVersion string   `json:"minOCPVersion,omitempty"`
}

// Plugins lists every network plugin choice, OVN-Kubernetes first.
func Plugins() []Plugin {
	min := fmt.Sprintf("4.%d", MinOCPMinor)
	return []Plugin{
		{NetworkType: OVNKubernetes, DisplayName: "OVN-Kubernetes"},
		{NetworkType: Calico, DisplayName: "Calico", Versions: Versions(Calico), MinOCPVersion: min},
		{NetworkType: Cilium, DisplayName: "Cilium", Versions: Versions(Cilium), MinOCPVersion: min},
	}
}

func dirOf(networkType string) string {
	switch networkType {
	case Calico:
		return "manifests/calico"
	case Cilium:
		return "manifests/cilium"
	}
	return ""
}

// Versions returns the embedded versions of a third-party plugin, newest first.
func Versions(networkType string) []string {
	dir := dirOf(networkType)
	if dir == "" {
		return nil
	}
	entries, err := fs.ReadDir(manifestsFS, dir)
	if err != nil {
		panic(err) // embedded at build time; a miss is a build bug
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() {
			out = append(out, e.Name())
		}
	}
	sort.Slice(out, func(i, j int) bool { return semverLess(out[j], out[i]) })
	return out
}

// Normalize returns the effective network type ("" means OVNKubernetes).
func Normalize(networkType string) string {
	if networkType == "" {
		return OVNKubernetes
	}
	return networkType
}

// IsThirdParty reports whether the network type needs embedded manifests.
func IsThirdParty(networkType string) bool { return dirOf(networkType) != "" }

// ResolveVersion returns the version to install: the requested one, or the
// newest embedded one when empty.
func ResolveVersion(networkType, version string) string {
	if version != "" {
		return version
	}
	if v := Versions(networkType); len(v) > 0 {
		return v[0]
	}
	return ""
}

// Validate checks a network plugin choice against the OpenShift version.
// Problems are returned as plain sentences (joined by the caller).
func Validate(networkType, version, ocpVersion string) []string {
	var problems []string
	nt := Normalize(networkType)
	if nt == OVNKubernetes {
		if version != "" {
			problems = append(problems, "network.cniVersion must be empty for OVNKubernetes (its version comes with OpenShift)")
		}
		return problems
	}
	if !IsThirdParty(nt) {
		return append(problems, fmt.Sprintf("network.networkType %q is not supported (use OVNKubernetes, Calico or Cilium)", networkType))
	}
	if version != "" && !contains(Versions(nt), version) {
		problems = append(problems, fmt.Sprintf("%s version %q is not offered (available: %s)", nt, version, strings.Join(Versions(nt), ", ")))
	}
	if minor, ok := ocpMinor(ocpVersion); ok && minor < MinOCPMinor {
		problems = append(problems, fmt.Sprintf("%s needs OpenShift 4.%d or later: the agent installer of %s only accepts OVNKubernetes", nt, MinOCPMinor, ocpVersion))
	}
	return problems
}

// Params are the per-cluster values substituted into the manifests.
type Params struct {
	NetworkType        string
	Version            string
	ClusterName        string
	BaseDomain         string
	ClusterNetworkCIDR string
}

func (p Params) apiIntHost() string { return "api-int." + p.ClusterName + "." + p.BaseDomain }

// Manifests returns the files for the install dir's openshift/ folder, keyed
// by file name (prefixed "cni-" so they never collide with the installer's).
// It returns nil for OVNKubernetes.
func Manifests(p Params) (map[string][]byte, error) {
	nt := Normalize(p.NetworkType)
	if !IsThirdParty(nt) {
		return nil, nil
	}
	version := ResolveVersion(nt, p.Version)
	if !contains(Versions(nt), version) {
		return nil, fmt.Errorf("%s version %q is not embedded", nt, version)
	}
	out := map[string][]byte{}

	// Upstream files, verbatim apart from the __SOS_*__ placeholders.
	vdir := path.Join(dirOf(nt), version)
	entries, err := fs.ReadDir(manifestsFS, vdir)
	if err != nil {
		return nil, err
	}
	repl := strings.NewReplacer(
		"__SOS_CLUSTER_NETWORK_CIDR__", p.ClusterNetworkCIDR,
		"__SOS_API_INT_HOST__", p.apiIntHost(),
	)
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".yaml") {
			continue
		}
		b, err := fs.ReadFile(manifestsFS, path.Join(vdir, e.Name()))
		if err != nil {
			return nil, err
		}
		out[fileName(nt, e.Name())] = []byte(repl.Replace(string(b)))
	}

	// Our own per-cluster files (manifests/<plugin>/*.yaml.tmpl).
	tmpls, err := fs.Glob(manifestsFS, path.Join(dirOf(nt), "*.yaml.tmpl"))
	if err != nil {
		return nil, err
	}
	data := map[string]string{
		"APIIntHost":         p.apiIntHost(),
		"ClusterNetworkCIDR": p.ClusterNetworkCIDR,
		"Version":            version,
	}
	for _, name := range tmpls {
		src, err := fs.ReadFile(manifestsFS, name)
		if err != nil {
			return nil, err
		}
		t, err := template.New(path.Base(name)).Option("missingkey=error").Parse(string(src))
		if err != nil {
			return nil, fmt.Errorf("parsing %s: %w", name, err)
		}
		var buf bytes.Buffer
		if err := t.Execute(&buf, data); err != nil {
			return nil, fmt.Errorf("rendering %s: %w", name, err)
		}
		out[fileName(nt, strings.TrimSuffix(path.Base(name), ".tmpl"))] = buf.Bytes()
	}
	return out, nil
}

// fileName keeps the upstream order (00-, 01-, ...) inside one plugin.
func fileName(networkType, base string) string {
	return "cni-" + strings.ToLower(networkType) + "-" + base
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// ocpMinor parses "4.22" or "4.22.3"; ok is false for anything else.
func ocpMinor(v string) (int, bool) {
	parts := strings.Split(v, ".")
	if len(parts) < 2 || parts[0] != "4" {
		return 0, false
	}
	m, err := strconv.Atoi(parts[1])
	return m, err == nil
}

// semverLess compares "v1.2.3" style versions numerically.
func semverLess(a, b string) bool {
	pa, pb := splitVersion(a), splitVersion(b)
	for i := 0; i < len(pa) && i < len(pb); i++ {
		if pa[i] != pb[i] {
			return pa[i] < pb[i]
		}
	}
	return len(pa) < len(pb)
}

func splitVersion(v string) []int {
	var out []int
	for _, s := range strings.Split(strings.TrimPrefix(v, "v"), ".") {
		n, _ := strconv.Atoi(s)
		out = append(out, n)
	}
	return out
}
